INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tgweb_english', '長文問題', 'ムラーノ島のガラス工芸', 'The Italian island of Murano, located in the Venetian Lagoon, has been famous for glassmaking since the medieval period. In 1291, the government of Venice ordered all glass furnaces to be moved to Murano, fearing that the intense heat of the furnaces would cause fires in the crowded city. This decision, intended as a safety measure, had an unexpected effect: it concentrated the region’s glassmakers on a single island, allowing techniques to be shared and refined more easily than before. Over time, Murano became synonymous with high-quality decorative glass.

Giulia Rossi is one of the island’s remaining master glassblowers. She learned the craft from her grandfather, who insisted that she practice shaping molten glass for years before being allowed to create her own designs. Rossi still uses a wood-fired furnace, believing that the heat produced this way gives the glass a smoother texture than electric furnaces do. When she started working full-time in 1998, there were more than 40 active furnaces on Murano. Today, fewer than 20 remain in operation.

Rossi often speaks of Antonio Seguso, a glassmaker who opened his workshop in 1859. At the time, most Murano glass was thick and heavily colored, made mainly for wealthy collectors. Seguso experimented with thinner glass and lighter, more transparent colors, which made his pieces suitable for everyday use rather than display alone. His approach influenced many glassmakers who followed him, and thin, clear glasswork remains a Murano specialty today.

In her workshop, Rossi keeps a sketch believed to have been drawn by Seguso himself. She shares Seguso’s conviction that glass objects should be beautiful without being impractical. Rossi has trained several apprentices over the past two decades, and in 2019, one of them helped her set up a small online store so customers abroad could purchase her work directly. Rossi now hopes to open her furnace to visitors on weekends, allowing tourists to watch traditional glassblowing and encouraging younger islanders to consider the craft as a career.

【設問】
Why were glass furnaces moved to Murano in 1291?', NULL, '["To reduce the risk of fire in the city of Venice.","To be closer to the source of raw materials.","To separate rival glassmaking families.","To take advantage of cheaper island labor."]', 0, '["第1段落：安全対策としてムラーノ島に炉が集められた → 火災防止が理由。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型英語: 長文問題）', 901);
