INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tgweb_english', '長文問題', 'ニュルンベルクの玩具づくり', 'Nuremberg, a city in southern Germany, has been associated with toymaking since the 14th century. Its position at the crossroads of several major trade routes allowed craftsmen easy access to wood, tin, and other materials from across Europe, while the city’s strong guild system ensured that toymaking skills were carefully taught and preserved. By the 19th century, Nuremberg was exporting toys to countries throughout the world, earning it the nickname “the toy capital of the world.”

Lukas Weber continues this legacy at his small workshop near Nuremberg’s old town. He specializes in hand-carved wooden toys, particularly articulated figures whose joints allow for movement, a technique requiring careful measurement and precise cutting. Weber began his training in 1991, when the city had around 18 small workshops producing wooden toys by hand. Today, fewer than seven such workshops remain, as plastic toys have largely replaced wooden ones in mass markets.

Weber often refers to Katharina Vogel, a toymaker who opened a workshop in Nuremberg in 1873. Before her innovations, wooden toys were typically painted with a limited range of dull colors that faded quickly. Vogel developed a more durable, brightly colored varnish using natural ingredients, which allowed toys to retain their appearance for many years. Her varnish technique was soon adopted throughout the city and became closely associated with Nuremberg’s reputation for high-quality toys.

A small tin of Vogel’s original varnish recipe, handwritten on aged paper, is framed on the wall of Weber’s workshop. Like Vogel, he believes that toys should be durable enough to be passed from one generation to the next. Weber has taught his craft to several apprentices over the years, and in 2019, one of them helped him arrange a booth at an international toy fair, where his work attracted considerable attention from collectors. Weber now hopes to open a small workshop tour program so that children and their families can watch traditional toymaking firsthand.

【設問】
What helped Nuremberg become known for toymaking?', NULL, '["Its access to trade routes for materials and its strong guild system.","A royal decree requiring all toys to be made there.","Its isolation from other major European cities.","A local law banning the import of foreign toys."]', 0, '["第1段落：交易路へのアクセスとギルド制度が技術の維持に寄与。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型英語: 長文問題）', 907);
