INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, passage_group_id) VALUES ('tgweb_english', '長文問題', 'テレマルクの木彫り家具（ローズマーリング）', 'Telemark, a region in southern Norway, has long been recognized for a distinctive style of wood carving and painted furniture known as rosemaling. The area’s dense forests provided abundant timber, while its relative isolation in mountainous terrain allowed local artistic styles to develop somewhat independently from those in other parts of Norway. By the 18th century, Telemark’s carved and painted chests, cabinets, and chairs were highly valued throughout the region.

Ingrid Haugen continues this craft in a small workshop near a Telemark fjord. She carves furniture from local pine and birch, then paints flowing floral patterns using brushes she makes herself from squirrel hair. Haugen began her training in 1994, when the area had about 20 workshops producing traditional rosemaling furniture. Today, only eight remain, as demand has shifted toward simpler, mass-produced furniture designs.

Haugen often mentions Ola Bergsland, a craftsman who opened a workshop in Telemark in 1856. Before his time, rosemaling patterns were fairly simple, often limited to basic borders and repeated shapes. Bergsland introduced more elaborate, flowing designs featuring vines, leaves, and stylized flowers that curved naturally across furniture surfaces. His approach required greater skill but produced far more dynamic and expressive results, and it strongly influenced the style still used by rosemaling artists today.

An old cabinet believed to have been painted by Bergsland stands in the corner of Haugen’s workshop. Like Bergsland, she believes that traditional crafts should evolve rather than remain frozen in their original form. Haugen has taught rosemaling to several students over the years, and in 2021, one of them helped her organize a small exhibition at a regional folk museum, which introduced her work to a wider audience. Haugen now hopes to offer short workshops for visitors, allowing them to try basic rosemaling techniques and better appreciate the skill involved in the craft.

【設問】
What allowed Telemark’s rosemaling style to develop somewhat independently?', NULL, '["Its dense forests and relative isolation in mountainous terrain.","A government law restricting travel between regions.","Its location along a major international trade route.","Its extremely mild and dry climate."]', 0, '["第1段落：豊かな森林と山岳地帯による隔絶が独自様式の発展を促した。"]', 4, 'published', 'ユーザー提供のオリジナル問題（TG-WEB新型英語: 長文問題）', 910);
